import{_ as o,o as a,c as s,a0 as i}from"./chunks/framework.DCluYYrN.js";const p=JSON.parse('{"title":"Diferenças com Magisk","description":"","frontmatter":{},"headers":[],"relativePath":"pt_BR/guide/difference-with-magisk.md","filePath":"pt_BR/guide/difference-with-magisk.md"}'),t={name:"pt_BR/guide/difference-with-magisk.md"};function d(r,e,m,n,l,c){return a(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="diferencas-com-magisk" tabindex="-1">Diferenças com Magisk <a class="header-anchor" href="#diferencas-com-magisk" aria-label="Permalink to &quot;Diferenças com Magisk&quot;">​</a></h1><p>Embora os módulos do KernelSU e do Magisk tenham muitas semelhanças, existem inevitavelmente algumas diferenças devido aos seus mecanismos de implementação completamente diferentes. Se você deseja que seu módulo funcione tanto no Magisk quanto no KernelSU, é essencial compreender essas diferenças.</p><h2 id="semelhancas" tabindex="-1">Semelhanças <a class="header-anchor" href="#semelhancas" aria-label="Permalink to &quot;Semelhanças&quot;">​</a></h2><ul><li>Formato de arquivo do módulo: Ambos usam o formato ZIP para organizar os módulos, e o formato dos módulos é praticamente o mesmo.</li><li>Diretório de instalação do módulo: Ambos estão localizados em <code>/data/adb/modules</code>.</li><li>Sem sistema: Ambos suportam a modificação de <code>/system</code> de forma sem sistema por meio de módulos.</li><li>post-fs-data.sh: O tempo de execução e a semântica são exatamente os mesmos.</li><li>service.sh: O tempo de execução e a semântica são exatamente os mesmos.</li><li>system.prop: Completamente o mesmo.</li><li>sepolicy.rule: Completamente o mesmo.</li><li>BusyBox: Os scripts são executados no BusyBox com o &quot;Modo Autônomo&quot; ativado em ambos os casos.</li></ul><h2 id="diferencas" tabindex="-1">Diferenças <a class="header-anchor" href="#diferencas" aria-label="Permalink to &quot;Diferenças&quot;">​</a></h2><p>Antes de entender as diferenças, é importante saber como identificar se o seu módulo está sendo executado no KernelSU ou no Magisk. Você pode usar a variável de ambiente <code>KSU</code> para diferenciá-lo em todos os locais onde você pode executar os scripts do módulo (<code>customize.sh</code>, <code>post-fs-data.sh</code>, <code>service.sh</code>). No KernelSU, essa variável de ambiente será definida como <code>true</code>.</p><p>Aqui estão algumas diferenças:</p><ul><li>Os módulos KernelSU não podem ser instalados no modo Recovery.</li><li>Os módulos KernelSU não oferece suporte nativo ao Zygisk, mas você pode usar módulos Zygisk através do <a href="https://github.com/Dr-TSNG/ZygiskNext" target="_blank" rel="noreferrer">ZygiskNext</a>.</li><li><strong>Arquitetura de montagem de módulos</strong>: KernelSU usa um <a href="./metamodule.html">sistema metamodule</a>, delegando a montagem a metamodules plugáveis (por exemplo, <code>meta-overlayfs</code>), enquanto o Magisk tem a montagem integrada em seu núcleo. KernelSU requer instalar um metamodule para habilitar a montagem de módulos.</li><li>O método para substituir ou excluir arquivos nos módulos do KernelSU é completamente diferente do Magisk. O KernelSU não suporta o método <code>.replace</code>. Em vez disso, você deve criar um arquivo com o comando <code>mknod filename c 0 0</code> para excluir o arquivo correspondente.</li><li>Os diretórios do BusyBox são diferentes. O BusyBox integrado no KernelSU está localizado em <code>/data/adb/ksu/bin/busybox</code>, enquanto no Magisk está em <code>/data/adb/magisk/busybox</code>. <strong>Observe que este é um comportamento interno do KernelSU e pode mudar no futuro!</strong></li><li>O KernelSU não suporta arquivos <code>.replace</code>, mas oferece suporte às variáveis ​​<code>REMOVE</code> e <code>REPLACE</code> para remover ou substituir arquivos e pastas.</li><li>O KernelSU adiciona um script <code>boot-completed.sh</code> para executar tarefas após a conclusão da inicialização do sistema Android.</li><li>O KernelSU adiciona um script <code>post-mount.sh</code> para executar tarefas após a conclusão da montagem do módulo.</li></ul>',8)])])}const f=o(t,[["render",d]]);export{p as __pageData,f as default};
